window.__finlexDocLoaded(10069,{"id":10069,"articles":[{"id":1000325,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"IFRIC 22 is effective 1 January 2018.\n\nIFRIC 22 clarifies which exchange rate to use in transactions that involve advance consideration paid or received in a foreign currency.","seq":0},{"id":1000326,"no":"History","heading":"Standard History & Amendments","text":"In December 2016 the International Accounting Standards Board issued IFRIC 22 Foreign Currency Transactions and Advance Consideration. It was developed by the Interpretations Committee.\n\nOther Standards have made minor consequential amendments to IFRIC 22, including IFRS 17 Insurance Contracts (issued May 2017) and Amendments to References to the Conceptual Framework in IFRS Standards (issued March 2018).","seq":1},{"id":1000327,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related active projects]\n[Related completed projects]\nForeign Currency Transactions and Advance Consideration (Amendments to IAS 21)\n[Related IFRS Standards]\nIAS 21 The Effects of Changes in Foreign Exchange Rates\n[Related IFRIC Interpretations]\n[Unconsolidated amendments]\n[Implementation support]","seq":2},{"id":1000328,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/ifric-22-foreign-currency-transactions-and-advance-consideration/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":3}]});
